    private static void OnMainWindowPreviewMouseDown(object sender, MouseButtonEventArgs e)
    {
        if (e.OriginalSource is not DependencyObject source) return;
        var button = FindParent<Button>(source);
        if (button?.Tag is not string tag || !tag.Equals("updater", StringComparison.OrdinalIgnoreCase)) return;
        if (sender is MainWindow window)
        {
            e.Handled = true;
            window.ShowSwitchPage(window.IsGerman ? "YACA Updater: derzeit nicht verfügbar. Zur YACA-Wechsel-Seite gewechselt." : "YACA Updater is currently unavailable. Opened the YACA switch page.");
        }
    }

    private static T? FindParent<T>(DependencyObject? current) where T : DependencyObject
    {
        while (current is not null)
        {
            if (current is T match) return match;
            current = current is Visual || current is Visual3D ? VisualTreeHelper.GetParent(current) : null;
        }
        return null;
    }
}
